import json, numpy as np
from itertools import product
h=json.load(open('/tmp/hist.json'))['runs']
rows=[(round(r['kl'],4), r['config']['method'], r['config']['len_pen'], r['proxy_reward'], r['mean_len']) for r in h if r['svc']=='train']
groups={}
for kl,m,lp,p,l in rows: groups.setdefault((kl,m),[]).append((lp,p,l))
for k,v in sorted(groups.items()):
    byl={}
    for lp,p,l in v: byl.setdefault(lp,[]).append((p,l))
    print(k, [(lp, round(np.mean([p for p,_ in x]),3), round(np.std([p for p,_ in x]),3), round(np.mean([l for _,l in x])), len(x)) for lp,x in sorted(byl.items())])
data=[(k,p,l) for k,v in groups.items() if len(v)>=2 for lp,p,l in v]
keys=sorted(set(k for k,_,_ in data))
y=np.array([p for _,p,_ in data]); lens=np.array([l for *_,l in data])
D=np.array([[1.0 if kk==k else 0.0 for kk in keys] for k,_,_ in data])
def fit(gfun):
    X=np.column_stack([D,gfun(lens)])
    beta,*_=np.linalg.lstsq(X,y,rcond=None)
    return np.sqrt(((X@beta-y)**2).mean()), beta
L0=280.0
res=[]
for L,k in product(np.linspace(20,250,116), [0.6,0.8,1.0,1.2,1.5,2.0,2.5]):
    g=lambda l: 1-np.exp(-(np.maximum(l-L0,0)/L)**k)
    r,b=fit(g); res.append((r,'weib',L,k,b))
for m,s in product(np.linspace(250,500,51), np.linspace(10,150,29)):
    g=lambda l: 1/(1+np.exp(-(l-m)/s)) - 1/(1+np.exp(-(L0-m)/s))
    r,b=fit(g); res.append((r,'logi',m,s,b))
for L in np.linspace(20,250,116):
    g=lambda l: np.tanh((l-L0)/L); r,b=fit(g); res.append((r,'tanh',L,0,b))
for L in np.linspace(20,400,191):
    g=lambda l: 1-np.exp(-(l-L0)/L); r,b=fit(g); res.append((r,'exp',L,0,b))
res.sort(key=lambda t:t[0])
seen=set()
for r,name,p1,p2,b in res[:40]:
    a=b[-1]
    if name=='weib': gv=a*(1-np.exp(-((780-L0)/p1)**p2))
    elif name=='logi': gv=a*(1/(1+np.exp(-(780-p1)/p2)) - 1/(1+np.exp(-(L0-p1)/p2)))
    elif name=='tanh': gv=a*np.tanh((780-L0)/p1)
    else: gv=a*(1-np.exp(-(780-L0)/p1))
    print(name,round(p1,1),round(p2,2),'rmse',round(r,4),'a',round(a,3),'g780',round(gv,3),'frac',round(gv/1.429,3),'off0',round(b[keys.index((0.0,'bon'))],3))
